export const MIGRATIONS: { name: string; sql: string }[] = [
  {
    "name": "20261001000001_schema.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · FINA CLÁSSICA + BRAVUS\n-- Migration 0001 — esquema principal\n--\n-- Compatível com PostgreSQL 15+ (Supabase) e PGlite (banco embutido do modo\n-- demonstração). Não depende de extensões: gen_random_uuid() é nativo.\n--\n-- Convenções:\n--   * brand_id em toda entidade comercialmente relevante (§1.2)\n--   * created_at / updated_at em todas as tabelas mutáveis\n--   * deleted_at = soft delete (§28.7)\n--   * is_demo = registros fictícios marcados explicitamente (§38)\n-- =============================================================================\n\ncreate or replace function public.set_updated_at() returns trigger\nlanguage plpgsql as $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\n\n-- -----------------------------------------------------------------------------\n-- Marcas\n-- -----------------------------------------------------------------------------\ncreate table public.brands (\n  id            uuid primary key default gen_random_uuid(),\n  slug          text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),\n  name          text not null,\n  audience      text,\n  positioning   text,\n  order_prefix  text not null unique check (order_prefix ~ '^[A-Z]{2,4}$'),\n  is_active     boolean not null default true,\n  sort_order    integer not null default 0,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\n\n-- -----------------------------------------------------------------------------\n-- Usuários, papéis e permissões (RBAC — §35)\n-- -----------------------------------------------------------------------------\ncreate table public.users (\n  id               uuid primary key default gen_random_uuid(),\n  full_name        text not null check (length(full_name) between 2 and 160),\n  nickname         text,\n  email            text not null check (position('@' in email) > 1),\n  phone            text,\n  whatsapp         text,\n  photo_url        text,\n  cpf_hash         text,              -- CPF nunca em texto puro (§26)\n  cpf_last_digits  text check (cpf_last_digits ~ '^[0-9]{2}$'),\n  birth_date       date,\n  password_hash    text,              -- scrypt (formato: scrypt$N$r$p$salt$hash)\n  status           text not null default 'pendente'\n                   check (status in ('ativo', 'inativo', 'suspenso', 'pendente')),\n  is_owner         boolean not null default false,   -- ADMINISTRADOR_PRINCIPAL\n  admission_date   date,\n  job_title        text,\n  notes            text,\n  mfa_required     boolean not null default false,\n  suspended_until  timestamptz,\n  created_by       uuid references public.users(id) on delete set null,\n  last_access_at   timestamptz,\n  is_demo          boolean not null default false,\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n  deleted_at       timestamptz\n);\ncreate unique index users_email_unique on public.users (lower(email)) where deleted_at is null;\n-- Só pode existir um ADMINISTRADOR_PRINCIPAL ativo.\ncreate unique index users_single_owner on public.users (is_owner) where is_owner and deleted_at is null;\ncreate index users_status_idx on public.users (status) where deleted_at is null;\n\ncreate table public.roles (\n  id             uuid primary key default gen_random_uuid(),\n  key            text not null unique check (key ~ '^[A-Z0-9_]+$'),\n  name           text not null,\n  description    text,\n  default_scope  text,\n  is_system      boolean not null default false,   -- papéis padrão: não podem ser excluídos\n  is_active      boolean not null default true,\n  created_by     uuid references public.users(id) on delete set null,\n  created_at     timestamptz not null default now(),\n  updated_at     timestamptz not null default now(),\n  deleted_at     timestamptz\n);\n\ncreate table public.permissions (\n  id           uuid primary key default gen_random_uuid(),\n  module       text not null check (module ~ '^[a-z_]+$'),\n  action       text not null check (action in ('visualizar', 'criar', 'editar', 'excluir', 'exportar',\n                                                'aprovar', 'configurar', 'convidar', 'revogar')),\n  description  text,\n  unique (module, action)\n);\n\ncreate table public.role_permissions (\n  role_id        uuid not null references public.roles(id) on delete cascade,\n  permission_id  uuid not null references public.permissions(id) on delete cascade,\n  primary key (role_id, permission_id)\n);\n\n-- Atribuição de papel com escopo de marca: brand_id NULL = todas as marcas.\ncreate table public.user_roles (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references public.users(id) on delete cascade,\n  role_id     uuid not null references public.roles(id),\n  brand_id    uuid references public.brands(id),\n  created_by  uuid references public.users(id) on delete set null,\n  created_at  timestamptz not null default now()\n);\ncreate unique index user_roles_unique\n  on public.user_roles (user_id, role_id, coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid));\ncreate index user_roles_user_idx on public.user_roles (user_id);\n\n-- Permissões customizadas por usuário (papel PERSONALIZADO).\ncreate table public.user_permissions (\n  id             uuid primary key default gen_random_uuid(),\n  user_id        uuid not null references public.users(id) on delete cascade,\n  permission_id  uuid not null references public.permissions(id) on delete cascade,\n  brand_id       uuid references public.brands(id),\n  created_by     uuid references public.users(id) on delete set null,\n  created_at     timestamptz not null default now()\n);\ncreate unique index user_permissions_unique\n  on public.user_permissions (user_id, permission_id, coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid));\n\ncreate table public.teams (\n  id           uuid primary key default gen_random_uuid(),\n  name         text not null,\n  description  text,\n  brand_id     uuid references public.brands(id),\n  is_demo      boolean not null default false,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\n\ncreate table public.team_members (\n  team_id     uuid not null references public.teams(id) on delete cascade,\n  user_id     uuid not null references public.users(id) on delete cascade,\n  created_at  timestamptz not null default now(),\n  primary key (team_id, user_id)\n);\n\ncreate table public.invitations (\n  id                uuid primary key default gen_random_uuid(),\n  email             text not null,\n  full_name         text,\n  job_title         text,\n  role_id           uuid not null references public.roles(id),\n  brand_id          uuid references public.brands(id),\n  token_hash        text not null unique,\n  status            text not null default 'pendente'\n                    check (status in ('pendente', 'aceito', 'expirado', 'revogado')),\n  expires_at        timestamptz not null,\n  accepted_at       timestamptz,\n  accepted_user_id  uuid references public.users(id) on delete set null,\n  invited_by        uuid references public.users(id) on delete set null,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now()\n);\ncreate index invitations_status_idx on public.invitations (status);\n\ncreate table public.password_resets (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references public.users(id) on delete cascade,\n  token_hash  text not null unique,\n  expires_at  timestamptz not null,\n  used_at     timestamptz,\n  created_by  uuid references public.users(id) on delete set null,\n  created_at  timestamptz not null default now()\n);\n\ncreate table public.sessions (\n  id            uuid primary key default gen_random_uuid(),\n  user_id       uuid not null references public.users(id) on delete cascade,\n  token_hash    text not null unique,     -- token bruto só existe no cookie httpOnly\n  ip            text,\n  user_agent    text,\n  created_at    timestamptz not null default now(),\n  last_seen_at  timestamptz not null default now(),\n  expires_at    timestamptz not null,\n  revoked_at    timestamptz\n);\ncreate index sessions_user_idx on public.sessions (user_id) where revoked_at is null;\n\ncreate table public.rate_limits (\n  key                text primary key,\n  hits               integer not null default 0,\n  window_started_at  timestamptz not null default now()\n);\n\n-- -----------------------------------------------------------------------------\n-- Catálogo\n-- -----------------------------------------------------------------------------\ncreate table public.categories (\n  id               uuid primary key default gen_random_uuid(),\n  brand_id         uuid not null references public.brands(id),\n  parent_id        uuid references public.categories(id) on delete set null,\n  slug             text not null check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),\n  name             text not null,\n  description      text,\n  kind             text not null default 'padrao' check (kind in ('padrao', 'novidades', 'promocoes')),\n  image_url        text,\n  sort_order       integer not null default 0,\n  is_active        boolean not null default true,\n  seo_title        text,\n  seo_description  text,\n  is_demo          boolean not null default false,\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n  deleted_at       timestamptz\n);\ncreate unique index categories_brand_slug on public.categories (brand_id, slug) where deleted_at is null;\ncreate index categories_brand_idx on public.categories (brand_id, sort_order) where deleted_at is null;\n\ncreate table public.suppliers (\n  id            uuid primary key default gen_random_uuid(),\n  brand_id      uuid references public.brands(id),        -- NULL = atende as duas marcas\n  name          text not null,\n  document      text,\n  contact_name  text,\n  phone         text,\n  whatsapp      text,\n  email         text,\n  address       text,\n  city          text,\n  state         text check (state is null or state ~ '^[A-Z]{2}$'),\n  notes         text,\n  is_active     boolean not null default true,\n  is_demo       boolean not null default false,\n  created_by    uuid references public.users(id) on delete set null,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\ncreate index suppliers_name_idx on public.suppliers (lower(name)) where deleted_at is null;\n\ncreate table public.products (\n  id                 uuid primary key default gen_random_uuid(),\n  brand_id           uuid not null references public.brands(id),\n  category_id        uuid references public.categories(id) on delete set null,\n  subcategory_id     uuid references public.categories(id) on delete set null,\n  sku                text not null,\n  slug               text not null check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),\n  name               text not null,\n  short_description  text,\n  long_description   text,\n  cost_price         numeric(12,2) check (cost_price is null or cost_price >= 0),\n  sale_price         numeric(12,2) not null check (sale_price >= 0),\n  promo_price        numeric(12,2) check (promo_price is null or (promo_price >= 0 and promo_price < sale_price)),\n  margin_percent     numeric(7,2) generated always as (\n                       case\n                         when cost_price is null or coalesce(promo_price, sale_price) <= 0 then null\n                         else round(((coalesce(promo_price, sale_price) - cost_price) / coalesce(promo_price, sale_price)) * 100, 2)\n                       end\n                     ) stored,\n  material           text,\n  supplier_id        uuid references public.suppliers(id) on delete set null,\n  min_stock          integer not null default 0 check (min_stock >= 0),\n  video_url          text,\n  status             text not null default 'rascunho' check (status in ('ativo', 'inativo', 'rascunho')),\n  is_new             boolean not null default false,\n  is_featured        boolean not null default false,\n  tags               text,\n  quantity_sold      integer not null default 0 check (quantity_sold >= 0),\n  seo_title          text,\n  seo_description    text,\n  created_by         uuid references public.users(id) on delete set null,\n  updated_by         uuid references public.users(id) on delete set null,\n  is_demo            boolean not null default false,\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now(),\n  deleted_at         timestamptz\n);\ncreate unique index products_brand_sku on public.products (brand_id, sku) where deleted_at is null;\ncreate unique index products_brand_slug on public.products (brand_id, slug) where deleted_at is null;\ncreate index products_brand_status_idx on public.products (brand_id, status) where deleted_at is null;\ncreate index products_category_idx on public.products (category_id) where deleted_at is null;\ncreate index products_name_idx on public.products (lower(name));\ncreate index products_created_idx on public.products (brand_id, created_at desc);\n\ncreate table public.product_variants (\n  id              uuid primary key default gen_random_uuid(),\n  product_id      uuid not null references public.products(id) on delete cascade,\n  brand_id        uuid not null references public.brands(id),\n  size            text,\n  color           text,\n  color_hex       text check (color_hex is null or color_hex ~ '^#[0-9a-fA-F]{6}$'),\n  sku             text not null,\n  price_override  numeric(12,2) check (price_override is null or price_override >= 0),\n  min_stock       integer not null default 0 check (min_stock >= 0),\n  weight_grams    integer check (weight_grams is null or weight_grams >= 0),\n  dimensions      text,\n  image_url       text,\n  is_active       boolean not null default true,\n  sort_order      integer not null default 0,\n  is_demo         boolean not null default false,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz\n);\ncreate unique index product_variants_brand_sku on public.product_variants (brand_id, sku) where deleted_at is null;\ncreate index product_variants_product_idx on public.product_variants (product_id) where deleted_at is null;\n\ncreate table public.product_images (\n  id          uuid primary key default gen_random_uuid(),\n  product_id  uuid not null references public.products(id) on delete cascade,\n  url         text not null,\n  alt         text,\n  sort_order  integer not null default 0,\n  created_at  timestamptz not null default now()\n);\ncreate index product_images_product_idx on public.product_images (product_id, sort_order);\n\n-- Saldo por variação e local (preparado para multi-CD — §13).\ncreate table public.inventory (\n  variant_id  uuid not null references public.product_variants(id) on delete cascade,\n  location    text not null default 'principal',\n  quantity    integer not null default 0 check (quantity >= 0),\n  updated_at  timestamptz not null default now(),\n  primary key (variant_id, location)\n);\n\n-- -----------------------------------------------------------------------------\n-- Clientes e pedidos\n-- -----------------------------------------------------------------------------\ncreate table public.customers (\n  id                uuid primary key default gen_random_uuid(),\n  name              text not null,\n  phone             text,\n  phone_normalized  text,\n  whatsapp          text,\n  email             text,\n  address           text,\n  city              text,\n  state             text check (state is null or state ~ '^[A-Z]{2}$'),\n  zip               text,\n  notes             text,\n  whatsapp_opt_in   boolean not null default false,\n  opt_in_at         timestamptz,\n  is_demo           boolean not null default false,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  deleted_at        timestamptz\n);\ncreate unique index customers_phone_unique on public.customers (phone_normalized)\n  where deleted_at is null and phone_normalized is not null;\ncreate index customers_name_idx on public.customers (lower(name)) where deleted_at is null;\n\ncreate sequence public.order_number_seq start 1;\n\ncreate table public.orders (\n  id                  uuid primary key default gen_random_uuid(),\n  brand_id            uuid not null references public.brands(id),\n  number              bigint not null unique default nextval('public.order_number_seq'),\n  customer_id         uuid references public.customers(id) on delete set null,\n  customer_name       text not null,\n  customer_phone      text not null,\n  customer_whatsapp   text,\n  customer_email      text,\n  address             text,\n  city                text,\n  state               text,\n  zip                 text,\n  notes               text,\n  subtotal            numeric(12,2) not null check (subtotal >= 0),\n  discount            numeric(12,2) not null default 0 check (discount >= 0),\n  shipping            numeric(12,2) not null default 0 check (shipping >= 0),\n  shipping_label      text,\n  total               numeric(12,2) not null check (total >= 0),\n  payment_method      text,\n  status              text not null default 'pedido_recebido' check (status in (\n                        'carrinho_abandonado', 'aguardando_confirmacao', 'pedido_recebido',\n                        'aguardando_pagamento', 'pago', 'em_preparacao', 'enviado',\n                        'entregue', 'cancelado', 'devolvido')),\n  delivery_method     text not null default 'link' check (delivery_method in ('link', 'api')),\n  whatsapp_url        text,\n  stock_committed     boolean not null default false,\n  revenue_registered  boolean not null default false,\n  source              text not null default 'loja' check (source in ('loja', 'painel')),\n  idempotency_key     text unique,\n  created_by          uuid references public.users(id) on delete set null,\n  updated_by          uuid references public.users(id) on delete set null,\n  is_demo             boolean not null default false,\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n  deleted_at          timestamptz\n);\ncreate index orders_brand_created_idx on public.orders (brand_id, created_at desc) where deleted_at is null;\ncreate index orders_status_idx on public.orders (status) where deleted_at is null;\ncreate index orders_customer_idx on public.orders (customer_id);\n\ncreate table public.order_items (\n  id            uuid primary key default gen_random_uuid(),\n  order_id      uuid not null references public.orders(id) on delete cascade,\n  product_id    uuid references public.products(id) on delete set null,\n  variant_id    uuid references public.product_variants(id) on delete set null,\n  product_name  text not null,\n  sku           text,\n  size          text,\n  color         text,\n  quantity      integer not null check (quantity > 0),\n  unit_price    numeric(12,2) not null check (unit_price >= 0),\n  unit_cost     numeric(12,2) check (unit_cost is null or unit_cost >= 0),   -- snapshot p/ CMV\n  total         numeric(12,2) not null check (total >= 0),\n  created_at    timestamptz not null default now()\n);\ncreate index order_items_order_idx on public.order_items (order_id);\ncreate index order_items_product_idx on public.order_items (product_id);\n\ncreate table public.order_status_history (\n  id           uuid primary key default gen_random_uuid(),\n  order_id     uuid not null references public.orders(id) on delete cascade,\n  from_status  text,\n  to_status    text not null,\n  note         text,\n  changed_by   uuid references public.users(id) on delete set null,\n  created_at   timestamptz not null default now()\n);\ncreate index order_status_history_order_idx on public.order_status_history (order_id, created_at);\n\n-- Toda movimentação de estoque gera histórico (§13, §28.5).\ncreate table public.inventory_movements (\n  id                   uuid primary key default gen_random_uuid(),\n  brand_id             uuid not null references public.brands(id),\n  product_id           uuid not null references public.products(id),\n  variant_id           uuid not null references public.product_variants(id),\n  location             text not null default 'principal',\n  type                 text not null check (type in ('cadastro', 'entrada', 'saida', 'ajuste', 'transferencia',\n                                                      'perda', 'devolucao', 'inventario', 'venda', 'cancelamento')),\n  quantity             integer not null,   -- delta com sinal\n  balance_before       integer not null,\n  balance_after        integer not null check (balance_after >= 0),\n  unit_cost            numeric(12,2),\n  total_cost           numeric(12,2),\n  supplier_id          uuid references public.suppliers(id) on delete set null,\n  order_id             uuid references public.orders(id) on delete set null,\n  reason               text,\n  notes                text,\n  responsible_user_id  uuid references public.users(id) on delete set null,\n  occurred_at          timestamptz not null default now(),\n  is_demo              boolean not null default false,\n  created_at           timestamptz not null default now()\n);\ncreate index inventory_movements_variant_idx on public.inventory_movements (variant_id, created_at desc);\ncreate index inventory_movements_brand_idx on public.inventory_movements (brand_id, created_at desc);\n\n-- -----------------------------------------------------------------------------\n-- Financeiro\n-- -----------------------------------------------------------------------------\ncreate table public.financial_entries (\n  id              uuid primary key default gen_random_uuid(),\n  brand_id        uuid references public.brands(id),\n  kind            text not null check (kind in ('venda', 'outra_receita', 'estorno')),\n  description     text not null,\n  amount          numeric(12,2) not null check ((kind = 'estorno' and amount < 0) or (kind <> 'estorno' and amount > 0)),\n  occurred_on     date not null default current_date,\n  order_id        uuid references public.orders(id) on delete set null,\n  payment_method  text,\n  category        text,\n  created_by      uuid references public.users(id) on delete set null,   -- lancado_por\n  is_demo         boolean not null default false,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz\n);\ncreate index financial_entries_period_idx on public.financial_entries (brand_id, occurred_on) where deleted_at is null;\n\ncreate table public.financial_expenses (\n  id                     uuid primary key default gen_random_uuid(),\n  brand_id               uuid references public.brands(id),\n  category               text not null check (category in ('compra_produtos', 'fornecedores', 'fretes',\n                                                           'despesas_operacionais', 'marketing', 'outros')),\n  description            text not null,\n  amount                 numeric(12,2) not null check (amount > 0),\n  occurred_on            date not null default current_date,\n  supplier_id            uuid references public.suppliers(id) on delete set null,\n  inventory_movement_id  uuid references public.inventory_movements(id) on delete set null,\n  created_by             uuid references public.users(id) on delete set null,\n  is_demo                boolean not null default false,\n  created_at             timestamptz not null default now(),\n  updated_at             timestamptz not null default now(),\n  deleted_at             timestamptz\n);\ncreate index financial_expenses_period_idx on public.financial_expenses (brand_id, occurred_on) where deleted_at is null;\n\n-- -----------------------------------------------------------------------------\n-- WhatsApp e automações (§9, §20)\n-- -----------------------------------------------------------------------------\ncreate table public.whatsapp_templates (\n  id          uuid primary key default gen_random_uuid(),\n  brand_id    uuid references public.brands(id),    -- NULL = modelo geral\n  key         text not null check (key in ('checkout', 'pedido_recebido', 'pagamento_confirmado',\n                                           'pedido_enviado', 'pedido_entregue', 'pos_venda', 'estoque_baixo')),\n  name        text not null,\n  body        text not null,\n  is_active   boolean not null default true,\n  updated_by  uuid references public.users(id) on delete set null,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now()\n);\ncreate unique index whatsapp_templates_unique\n  on public.whatsapp_templates (coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid), key);\n\ncreate table public.whatsapp_messages_log (\n  id                   uuid primary key default gen_random_uuid(),\n  brand_id             uuid references public.brands(id),\n  order_id             uuid references public.orders(id) on delete set null,\n  customer_id          uuid references public.customers(id) on delete set null,\n  to_number            text,\n  template_key         text,\n  body                 text not null,\n  delivery_method      text not null check (delivery_method in ('link', 'api')),\n  status               text not null check (status in ('gerado', 'enviado', 'falhou')),\n  provider_message_id  text,\n  error                text,\n  created_by           uuid references public.users(id) on delete set null,\n  is_demo              boolean not null default false,\n  created_at           timestamptz not null default now()\n);\ncreate index whatsapp_messages_log_order_idx on public.whatsapp_messages_log (order_id);\ncreate index whatsapp_messages_log_created_idx on public.whatsapp_messages_log (created_at desc);\n\ncreate table public.automations (\n  id               uuid primary key default gen_random_uuid(),\n  brand_id         uuid references public.brands(id),\n  trigger_event    text not null check (trigger_event in ('pedido_recebido', 'pagamento_confirmado', 'pedido_enviado',\n                                                          'pedido_entregue', 'pos_venda', 'estoque_baixo')),\n  template_key     text not null,\n  is_enabled       boolean not null default false,\n  require_opt_in   boolean not null default true,\n  delay_minutes    integer not null default 0 check (delay_minutes >= 0),\n  notes            text,\n  updated_by       uuid references public.users(id) on delete set null,\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now()\n);\ncreate unique index automations_unique\n  on public.automations (coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid), trigger_event);\n\n-- -----------------------------------------------------------------------------\n-- CMS, banners, ideias, planejamento\n-- -----------------------------------------------------------------------------\ncreate table public.banners (\n  id            uuid primary key default gen_random_uuid(),\n  brand_id      uuid not null references public.brands(id),\n  placement     text not null check (placement in ('home_hero', 'home_secundario', 'categoria', 'produto')),\n  title         text,\n  subtitle      text,\n  cta_label     text,\n  image_url     text,\n  link_url      text,\n  category_id   uuid references public.categories(id) on delete set null,\n  sort_order    integer not null default 0,\n  is_active     boolean not null default true,\n  starts_at     timestamptz,\n  ends_at       timestamptz,\n  published_by  uuid references public.users(id) on delete set null,\n  is_demo       boolean not null default false,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\ncreate index banners_brand_idx on public.banners (brand_id, placement, sort_order) where deleted_at is null;\n\ncreate table public.cms_content (\n  id            uuid primary key default gen_random_uuid(),\n  brand_id      uuid references public.brands(id),   -- NULL = configuração geral\n  key           text not null,\n  value         jsonb not null default '{}'::jsonb,\n  published_by  uuid references public.users(id) on delete set null,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\ncreate unique index cms_content_unique\n  on public.cms_content (coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid), key);\n\ncreate table public.ideas (\n  id                   uuid primary key default gen_random_uuid(),\n  brand_id             uuid references public.brands(id),\n  title                text not null,\n  description          text,\n  category             text,\n  priority             text not null default 'media' check (priority in ('baixa', 'media', 'alta', 'urgente')),\n  status               text not null default 'ideia' check (status in ('ideia', 'planejado', 'em_andamento', 'concluido', 'cancelado')),\n  responsible_user_id  uuid references public.users(id) on delete set null,\n  idea_date            date not null default current_date,\n  notes                text,\n  created_by           uuid references public.users(id) on delete set null,\n  is_demo              boolean not null default false,\n  created_at           timestamptz not null default now(),\n  updated_at           timestamptz not null default now(),\n  deleted_at           timestamptz\n);\n\ncreate table public.planned_products (\n  id                uuid primary key default gen_random_uuid(),\n  brand_id          uuid not null references public.brands(id),\n  name              text not null,\n  category_id       uuid references public.categories(id) on delete set null,\n  supplier_id       uuid references public.suppliers(id) on delete set null,\n  estimated_cost    numeric(12,2) check (estimated_cost is null or estimated_cost >= 0),\n  estimated_price   numeric(12,2) check (estimated_price is null or estimated_price >= 0),\n  planned_quantity  integer check (planned_quantity is null or planned_quantity >= 0),\n  notes             text,\n  status            text not null default 'pesquisa' check (status in ('pesquisa', 'cotacao', 'aguardando_compra',\n                                                                     'comprado', 'cadastrado', 'disponivel')),\n  created_by        uuid references public.users(id) on delete set null,\n  is_demo           boolean not null default false,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  deleted_at        timestamptz\n);\n\n-- -----------------------------------------------------------------------------\n-- Auditoria, analytics e configurações gerais\n-- -----------------------------------------------------------------------------\ncreate table public.audit_logs (\n  id             uuid primary key default gen_random_uuid(),\n  actor_user_id  uuid references public.users(id) on delete set null,\n  actor_name     text,\n  actor_email    text,\n  action         text not null,\n  entity         text not null,\n  entity_id      text,\n  brand_id       uuid references public.brands(id),\n  before         jsonb,\n  after          jsonb,\n  reason         text,\n  ip             text,\n  user_agent     text,\n  created_at     timestamptz not null default now()\n);\ncreate index audit_logs_created_idx on public.audit_logs (created_at desc);\ncreate index audit_logs_actor_idx on public.audit_logs (actor_user_id, created_at desc);\ncreate index audit_logs_entity_idx on public.audit_logs (entity, entity_id);\n\ncreate table public.analytics_events (\n  id          uuid primary key default gen_random_uuid(),\n  brand_id    uuid references public.brands(id),\n  visitor_id  text,\n  type        text not null check (type in ('page_view', 'product_view', 'add_to_cart', 'begin_checkout',\n                                            'order_created', 'purchase_confirmed')),\n  product_id  uuid references public.products(id) on delete set null,\n  order_id    uuid references public.orders(id) on delete set null,\n  value       numeric(12,2),\n  path        text,\n  is_demo     boolean not null default false,\n  created_at  timestamptz not null default now()\n);\ncreate index analytics_events_idx on public.analytics_events (brand_id, type, created_at);\n\ncreate table public.app_settings (\n  key         text primary key,\n  value       jsonb not null default '{}'::jsonb,\n  updated_by  uuid references public.users(id) on delete set null,\n  updated_at  timestamptz not null default now()\n);\n\n-- -----------------------------------------------------------------------------\n-- Gatilhos de updated_at\n-- -----------------------------------------------------------------------------\ndo $$\ndeclare\n  t text;\nbegin\n  for t in\n    select c.table_name\n    from information_schema.columns c\n    where c.table_schema = 'public' and c.column_name = 'updated_at'\n  loop\n    execute format(\n      'create trigger %I before update on public.%I for each row execute function public.set_updated_at()',\n      t || '_set_updated_at', t\n    );\n  end loop;\nend;\n$$;\n"
  },
  {
    "name": "20261001000002_seed_base.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · Migration 0002 — dados-base do sistema\n--\n-- Somente o que está definido na especificação: marcas, categorias, papéis,\n-- permissões, modelos de mensagem e configurações com PLACEHOLDERS explícitos.\n-- Nenhum dado comercial (preço, cliente, fornecedor, logo, telefone) é criado.\n-- =============================================================================\n\n-- Marcas (§1.1)\ninsert into public.brands (slug, name, audience, positioning, order_prefix, sort_order) values\n  ('fina-classica', 'FINA CLÁSSICA', 'Feminino',  'Fino, elegante, clássico, sofisticado', 'FC', 1),\n  ('bravus',        'BRAVUS',        'Masculino', 'Elegante, moderno, forte, sofisticado', 'BR', 2);\n\n-- Categorias iniciais (§3.1) — todas editáveis pelo painel.\ninsert into public.categories (brand_id, slug, name, kind, sort_order)\nselect b.id, c.slug, c.name, c.kind, c.sort_order\nfrom public.brands b\njoin (values\n  ('fina-classica', 'vestidos',   'Vestidos',   'padrao',    1),\n  ('fina-classica', 'camisas',    'Camisas',    'padrao',    2),\n  ('fina-classica', 'blusas',     'Blusas',     'padrao',    3),\n  ('fina-classica', 'calcas',     'Calças',     'padrao',    4),\n  ('fina-classica', 'saias',      'Saias',      'padrao',    5),\n  ('fina-classica', 'bolsas',     'Bolsas',     'padrao',    6),\n  ('fina-classica', 'sapatos',    'Sapatos',    'padrao',    7),\n  ('fina-classica', 'acessorios', 'Acessórios', 'padrao',    8),\n  ('fina-classica', 'novidades',  'Novidades',  'novidades', 9),\n  ('fina-classica', 'promocoes',  'Promoções',  'promocoes', 10),\n  ('bravus',        'camisas',    'Camisas',    'padrao',    1),\n  ('bravus',        'camisetas',  'Camisetas',  'padrao',    2),\n  ('bravus',        'calcas',     'Calças',     'padrao',    3),\n  ('bravus',        'bermudas',   'Bermudas',   'padrao',    4),\n  ('bravus',        'bolsas',     'Bolsas',     'padrao',    5),\n  ('bravus',        'sapatos',    'Sapatos',    'padrao',    6),\n  ('bravus',        'acessorios', 'Acessórios', 'padrao',    7),\n  ('bravus',        'novidades',  'Novidades',  'novidades', 8),\n  ('bravus',        'promocoes',  'Promoções',  'promocoes', 9)\n) as c(brand_slug, slug, name, kind, sort_order) on c.brand_slug = b.slug;\n\n-- Permissões: módulo × ação (§35.3). O módulo \"cms\" separa identidade visual\n-- (marketing) de \"configuracoes\" (parâmetros do sistema).\ninsert into public.permissions (module, action)\nselect m, a\nfrom unnest(array[\n  'produtos', 'categorias', 'estoque', 'pedidos', 'clientes', 'fornecedores',\n  'financeiro', 'relatorios', 'analytics', 'whatsapp', 'automacoes',\n  'banners', 'cms', 'ideias', 'produtos_planejados', 'usuarios', 'permissoes',\n  'configuracoes', 'auditoria'\n]) as m\ncross join unnest(array[\n  'visualizar', 'criar', 'editar', 'excluir', 'exportar', 'aprovar', 'configurar', 'convidar', 'revogar'\n]) as a;\n\n-- Papéis pré-definidos (§35.2)\ninsert into public.roles (key, name, description, default_scope, is_system) values\n  ('ADMINISTRADOR_PRINCIPAL', 'Administrador principal', 'Dono/proprietário da conta. Acesso total irrevogável.', 'Tudo', true),\n  ('SOCIO',         'Sócio',         'Sócio com acesso amplo, mas não pode excluir o admin principal.', 'Tudo, exceto deletar admin principal e alterar plano de cobrança', true),\n  ('GERENTE',       'Gerente',       'Gerencia operação do dia a dia.', 'Produtos, pedidos, estoque, clientes, relatórios, equipe (leitura)', true),\n  ('VENDEDOR',      'Vendedor',      'Atende clientes e registra pedidos.', 'Pedidos, clientes, produtos (leitura)', true),\n  ('ESTOQUE',       'Estoque',       'Cuida de inventário e movimentações.', 'Estoque, produtos (leitura), fornecedores (leitura)', true),\n  ('FINANCEIRO',    'Financeiro',    'Cuida de contas, DRE, relatórios financeiros.', 'Financeiro, relatórios financeiros, pedidos (leitura)', true),\n  ('MARKETING',     'Marketing',     'Cuida de banners, CMS, campanhas e automações.', 'CMS, banners, automações, analytics (leitura)', true),\n  ('PERSONALIZADO', 'Personalizado', 'Papel customizado criado pelo admin com permissões granulares.', 'Definido pelo admin', true);\n\n-- Matriz padrão de cada papel\ninsert into public.role_permissions (role_id, permission_id)\nselect r.id, p.id\nfrom public.roles r\njoin public.permissions p on (\n  r.key in ('ADMINISTRADOR_PRINCIPAL', 'SOCIO')\n  or (r.key = 'GERENTE' and (\n        (p.module in ('produtos', 'categorias', 'estoque', 'pedidos', 'clientes')\n           and p.action in ('visualizar', 'criar', 'editar', 'excluir', 'exportar', 'aprovar'))\n     or (p.module = 'relatorios' and p.action in ('visualizar', 'exportar'))\n     or (p.module = 'usuarios' and p.action = 'visualizar')))\n  or (r.key = 'VENDEDOR' and (\n        (p.module in ('pedidos', 'clientes') and p.action in ('visualizar', 'criar', 'editar'))\n     or (p.module = 'produtos' and p.action = 'visualizar')))\n  or (r.key = 'ESTOQUE' and (\n        (p.module = 'estoque' and p.action in ('visualizar', 'criar', 'editar', 'exportar'))\n     or (p.module in ('produtos', 'fornecedores') and p.action = 'visualizar')))\n  or (r.key = 'FINANCEIRO' and (\n        (p.module = 'financeiro' and p.action in ('visualizar', 'criar', 'editar', 'excluir', 'exportar', 'aprovar'))\n     or (p.module = 'relatorios' and p.action in ('visualizar', 'exportar'))\n     or (p.module = 'pedidos' and p.action = 'visualizar')))\n  or (r.key = 'MARKETING' and (\n        (p.module = 'cms' and p.action in ('visualizar', 'editar', 'configurar'))\n     or (p.module = 'banners' and p.action in ('visualizar', 'criar', 'editar', 'excluir'))\n     or (p.module = 'automacoes' and p.action in ('visualizar', 'criar', 'editar', 'configurar'))\n     or (p.module = 'analytics' and p.action = 'visualizar')))\n);\n\n-- Modelos de mensagem do WhatsApp (§9.2 e §20)\ninsert into public.whatsapp_templates (brand_id, key, name, body) values\n  (null, 'checkout', 'Finalização do pedido (cliente → loja)',\n'Olá! Gostaria de realizar um pedido.\n\nLoja: {marca}\nPedido: #{numero}\n\nProdutos:\n{itens}\n\nSubtotal: {subtotal}\nFrete: {frete}\nTotal: {total}\n\nNome: {nome}\nTelefone: {telefone}\nObservações: {obs}\n\nGostaria de confirmar meu pedido.'),\n  (null, 'pedido_recebido', 'Pedido recebido',\n'Olá, {nome}! Recebemos o seu pedido #{pedido} na {marca}, no valor de {valor}. Em breve confirmaremos os detalhes por aqui.'),\n  (null, 'pagamento_confirmado', 'Pagamento confirmado',\n'Olá, {nome}! O pagamento do pedido #{pedido} ({valor}) foi confirmado em {data}. Obrigado por comprar na {marca}!'),\n  (null, 'pedido_enviado', 'Pedido enviado',\n'Olá, {nome}! O seu pedido #{pedido} da {marca} foi enviado em {data}. {link}'),\n  (null, 'pedido_entregue', 'Pedido entregue',\n'Olá, {nome}! Consta que o seu pedido #{pedido} da {marca} foi entregue. Qualquer dúvida, estamos por aqui.'),\n  (null, 'pos_venda', 'Pós-venda',\n'Olá, {nome}! Como foi a sua experiência com o pedido #{pedido} da {marca}? A sua opinião é muito importante para nós.'),\n  (null, 'estoque_baixo', 'Estoque baixo (alerta interno)',\n'Alerta de estoque na {marca}: {produto} está com estoque baixo. Verifique a reposição.');\n\n-- Automações: todas DESLIGADAS e exigindo opt-in (§20 — nada é enviado sem API + opt-in).\ninsert into public.automations (brand_id, trigger_event, template_key, is_enabled, require_opt_in)\nselect null, t, t, false, true\nfrom unnest(array['pedido_recebido', 'pagamento_confirmado', 'pedido_enviado',\n                  'pedido_entregue', 'pos_venda', 'estoque_baixo']) as t;\n\n-- Conteúdo do CMS com placeholders explícitos (§4: nunca inventar logos/cores oficiais/dados).\ninsert into public.cms_content (brand_id, key, value)\nselect b.id, v.key, v.value::jsonb\nfrom public.brands b\njoin (values\n  ('fina-classica', 'identity', '{\n     \"logo_url\": null, \"logo_placeholder\": \"[LOGO FINA — A DEFINIR]\", \"favicon_url\": null,\n     \"tagline\": \"Elegância · Sofisticação · Clássico\", \"card_subtitle\": \"Moda feminina\",\n     \"palette\": {\"primary\": \"#3A2F29\", \"secondary\": \"#E9E1DA\", \"accent\": \"#B39256\", \"text\": \"#2A2320\", \"background\": \"#F6F2EF\"},\n     \"palette_is_placeholder\": true,\n     \"typography\": {\"display\": \"Bodoni Moda\", \"body\": \"Jost\"}\n   }'),\n  ('bravus', 'identity', '{\n     \"logo_url\": null, \"logo_placeholder\": \"[LOGO BRAVUS — A DEFINIR]\", \"favicon_url\": null,\n     \"tagline\": \"Estilo · Elegância · Personalidade\", \"card_subtitle\": \"Moda masculina\",\n     \"palette\": {\"primary\": \"#2C2D30\", \"secondary\": \"#2C2D30\", \"accent\": \"#B87333\", \"text\": \"#ECE7E1\", \"background\": \"#1E1F21\"},\n     \"palette_is_placeholder\": true,\n     \"typography\": {\"display\": \"Barlow Condensed\", \"body\": \"Barlow\"}\n   }'),\n  ('fina-classica', 'home', '{\"hero_title\": null, \"hero_subtitle\": null, \"hero_image_url\": null, \"institutional_images\": []}'),\n  ('bravus',        'home', '{\"hero_title\": null, \"hero_subtitle\": null, \"hero_image_url\": null, \"institutional_images\": []}'),\n  ('fina-classica', 'contact', '{\"whatsapp\": null, \"email\": null, \"phone\": null, \"address\": null}'),\n  ('bravus',        'contact', '{\"whatsapp\": null, \"email\": null, \"phone\": null, \"address\": null}'),\n  ('fina-classica', 'social', '{\"instagram\": null, \"facebook\": null, \"tiktok\": null, \"pinterest\": null, \"youtube\": null}'),\n  ('bravus',        'social', '{\"instagram\": null, \"facebook\": null, \"tiktok\": null, \"pinterest\": null, \"youtube\": null}'),\n  ('fina-classica', 'policies', '{\"troca\": null, \"devolucao\": null, \"entrega\": null, \"privacidade\": null, \"termos\": null}'),\n  ('bravus',        'policies', '{\"troca\": null, \"devolucao\": null, \"entrega\": null, \"privacidade\": null, \"termos\": null}'),\n  ('fina-classica', 'seo', '{\"title\": null, \"description\": null, \"og_image_url\": null}'),\n  ('bravus',        'seo', '{\"title\": null, \"description\": null, \"og_image_url\": null}'),\n  ('fina-classica', 'shipping', '{\"mode\": \"a_combinar\", \"fixed_amount\": null, \"free_over\": null, \"notes\": null}'),\n  ('bravus',        'shipping', '{\"mode\": \"a_combinar\", \"fixed_amount\": null, \"free_over\": null, \"notes\": null}'),\n  ('fina-classica', 'whatsapp', '{\"number\": null, \"driver\": \"link\", \"cloud_phone_number_id\": null}'),\n  ('bravus',        'whatsapp', '{\"number\": null, \"driver\": \"link\", \"cloud_phone_number_id\": null}')\n) as v(brand_slug, key, value) on v.brand_slug = b.slug;\n\ninsert into public.cms_content (brand_id, key, value) values\n  (null, 'site', '{\"name\": \"FINA CLÁSSICA + BRAVUS\", \"selection_title\": \"ESCOLHA SUA EXPERIÊNCIA\", \"favicon_url\": null}'),\n  (null, 'whatsapp', '{\"number\": null}');\n\ninsert into public.app_settings (key, value) values\n  ('general', '{\"new_product_days\": 30, \"invite_expiration_hours\": 72, \"session_hours\": 12}');\n"
  },
  {
    "name": "20261001000003_security.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · Migration 0003 — segurança (RBAC no banco + Row Level Security)\n--\n-- Camadas:\n--   1. A aplicação (servidor Next.js) valida sessão e permissão em TODA ação\n--      (src/server/rbac). Ela conecta com a role do banco via DATABASE_URL.\n--   2. RLS habilitado em TODAS as tabelas: a API pública do Supabase\n--      (chave anon) só enxerga o catálogo publicado — nada de pedidos,\n--      clientes, financeiro, usuários ou sessões.\n--   3. Para usuários autenticados pela API do Supabase (auth.uid() = users.id),\n--      cada tabela tem políticas por papel × marca via has_permission().\n-- =============================================================================\n\ncreate or replace function public.has_permission(\n  p_user   uuid,\n  p_module text,\n  p_action text,\n  p_brand  uuid default null\n) returns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    exists (\n      select 1 from public.users u\n      where u.id = p_user and u.deleted_at is null and u.status = 'ativo' and u.is_owner\n    )\n    or exists (\n      select 1\n      from public.users u\n      join public.user_roles ur        on ur.user_id = u.id\n      join public.roles r              on r.id = ur.role_id and r.is_active and r.deleted_at is null\n      join public.role_permissions rp  on rp.role_id = r.id\n      join public.permissions p        on p.id = rp.permission_id\n      where u.id = p_user and u.deleted_at is null and u.status = 'ativo'\n        and p.module = p_module and p.action = p_action\n        and (ur.brand_id is null or p_brand is null or ur.brand_id = p_brand)\n    )\n    or exists (\n      select 1\n      from public.users u\n      join public.user_permissions up on up.user_id = u.id\n      join public.permissions p       on p.id = up.permission_id\n      where u.id = p_user and u.deleted_at is null and u.status = 'ativo'\n        and p.module = p_module and p.action = p_action\n        and (up.brand_id is null or p_brand is null or up.brand_id = p_brand)\n    );\n$$;\n\n-- RLS em todas as tabelas do schema public.\ndo $$\ndeclare\n  t text;\nbegin\n  for t in select tablename from pg_tables where schemaname = 'public' loop\n    execute format('alter table public.%I enable row level security', t);\n  end loop;\nend;\n$$;\n\n-- Políticas para a API do Supabase (só criadas quando as roles existem —\n-- no banco embutido do modo demonstração elas não existem).\ndo $$\ndeclare\n  rec record;\n  brand_expr text;\nbegin\n  if exists (select 1 from pg_roles where rolname = 'anon') then\n    -- Catálogo público (somente leitura, somente conteúdo publicado).\n    create policy catalogo_publico on public.brands for select to anon using (is_active);\n    create policy catalogo_publico on public.categories for select to anon\n      using (is_active and deleted_at is null);\n    create policy catalogo_publico on public.products for select to anon\n      using (status = 'ativo' and deleted_at is null);\n    create policy catalogo_publico on public.product_variants for select to anon\n      using (is_active and deleted_at is null\n             and exists (select 1 from public.products p where p.id = product_id and p.status = 'ativo' and p.deleted_at is null));\n    create policy catalogo_publico on public.product_images for select to anon\n      using (exists (select 1 from public.products p where p.id = product_id and p.status = 'ativo' and p.deleted_at is null));\n    create policy catalogo_publico on public.inventory for select to anon using (true);\n    create policy catalogo_publico on public.banners for select to anon\n      using (is_active and deleted_at is null);\n    create policy catalogo_publico on public.cms_content for select to anon using (true);\n  end if;\n\n  if exists (select 1 from pg_roles where rolname = 'authenticated')\n     and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                 where n.nspname = 'auth' and p.proname = 'uid') then\n    for rec in\n      select * from (values\n        ('products',              'produtos',            true),\n        ('product_variants',      'produtos',            true),\n        ('product_images',        'produtos',            false),\n        ('categories',            'categorias',          true),\n        ('inventory',             'estoque',             false),\n        ('inventory_movements',   'estoque',             true),\n        ('suppliers',             'fornecedores',        true),\n        ('customers',             'clientes',            false),\n        ('orders',                'pedidos',             true),\n        ('order_items',           'pedidos',             false),\n        ('order_status_history',  'pedidos',             false),\n        ('financial_entries',     'financeiro',          true),\n        ('financial_expenses',    'financeiro',          true),\n        ('whatsapp_templates',    'automacoes',          true),\n        ('automations',           'automacoes',          true),\n        ('whatsapp_messages_log', 'whatsapp',            true),\n        ('banners',               'banners',             true),\n        ('cms_content',           'cms',                 true),\n        ('ideas',                 'ideias',              true),\n        ('planned_products',      'produtos_planejados', true),\n        ('audit_logs',            'auditoria',           true),\n        ('analytics_events',      'analytics',           true),\n        ('users',                 'usuarios',            false),\n        ('user_roles',            'usuarios',            true),\n        ('user_permissions',      'usuarios',            true),\n        ('teams',                 'usuarios',            true),\n        ('team_members',          'usuarios',            false),\n        ('invitations',           'usuarios',            true),\n        ('roles',                 'permissoes',          false),\n        ('role_permissions',      'permissoes',          false),\n        ('permissions',           'permissoes',          false),\n        ('app_settings',          'configuracoes',       false)\n      ) as m(tbl, module, has_brand)\n    loop\n      brand_expr := case when rec.has_brand then 'brand_id' else 'null::uuid' end;\n      execute format(\n        'create policy rbac_select on public.%I for select to authenticated using (public.has_permission(auth.uid(), %L, %L, %s))',\n        rec.tbl, rec.module, 'visualizar', brand_expr);\n      execute format(\n        'create policy rbac_insert on public.%I for insert to authenticated with check (public.has_permission(auth.uid(), %L, %L, %s))',\n        rec.tbl, rec.module, 'criar', brand_expr);\n      execute format(\n        'create policy rbac_update on public.%I for update to authenticated using (public.has_permission(auth.uid(), %L, %L, %s))',\n        rec.tbl, rec.module, 'editar', brand_expr);\n      execute format(\n        'create policy rbac_delete on public.%I for delete to authenticated using (public.has_permission(auth.uid(), %L, %L, %s))',\n        rec.tbl, rec.module, 'excluir', brand_expr);\n    end loop;\n  end if;\nend;\n$$;\n-- sessions, password_resets e rate_limits ficam sem nenhuma política:\n-- inacessíveis pela API pública em qualquer caso.\n"
  },
  {
    "name": "20261001000004_hardening.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · Migration 0004 — ajustes do Security Advisor do Supabase\n--\n--   * set_updated_at com search_path fixo.\n--   * has_permission() não pode ser chamada pela chave pública (anon) via\n--     /rest/v1/rpc; continua disponível para \"authenticated\" porque as\n--     políticas RLS dependem dela.\n-- =============================================================================\n\nalter function public.set_updated_at() set search_path = public;\n\nrevoke execute on function public.has_permission(uuid, text, text, uuid) from public;\n\ndo $$\nbegin\n  if exists (select 1 from pg_roles where rolname = 'anon') then\n    execute 'revoke execute on function public.has_permission(uuid, text, text, uuid) from anon';\n  end if;\n  if exists (select 1 from pg_roles where rolname = 'authenticated') then\n    execute 'grant execute on function public.has_permission(uuid, text, text, uuid) to authenticated';\n  end if;\nend;\n$$;\n"
  },
  {
    "name": "20261001000005_logos_oficiais.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · Migration 0005 — logos oficiais e estilo visual de cada marca\n--\n-- Logos enviados pelo cliente (arquivos em public/brand/). Só preenche o que\n-- ainda está vazio, para não sobrescrever o que já foi publicado no painel.\n--   * look: \"classico\" (FINA CLÁSSICA) | \"urbano\" (BRAVUS) — define os efeitos\n--     visuais da loja (molduras, animações, texturas).\n--   * logo_shows_name: o logo da BRAVUS já traz o nome escrito.\n--   * Paleta BRAVUS derivada do logo (grafite + dourado), aplicada apenas se a\n--     paleta ainda for a sugestão original.\n-- =============================================================================\n\nupdate public.cms_content c\nset value = c.value\n  || jsonb_build_object(\n       'logo_url',        coalesce(c.value->>'logo_url', '/brand/fina-classica/logo.svg'),\n       'favicon_url',     coalesce(c.value->>'favicon_url', '/brand/fina-classica/icon.png'),\n       'look',            coalesce(c.value->>'look', 'classico'),\n       'logo_shows_name', coalesce((c.value->>'logo_shows_name')::boolean, false)\n     )\nfrom public.brands b\nwhere c.brand_id = b.id and b.slug = 'fina-classica' and c.key = 'identity';\n\nupdate public.cms_content c\nset value = c.value\n  || jsonb_build_object(\n       'logo_url',        coalesce(c.value->>'logo_url', '/brand/bravus/logo.webp'),\n       'favicon_url',     coalesce(c.value->>'favicon_url', '/brand/bravus/icon.png'),\n       'look',            coalesce(c.value->>'look', 'urbano'),\n       'logo_shows_name', coalesce((c.value->>'logo_shows_name')::boolean, true)\n     )\nfrom public.brands b\nwhere c.brand_id = b.id and b.slug = 'bravus' and c.key = 'identity';\n\nupdate public.cms_content c\nset value = jsonb_set(c.value, '{palette}',\n      '{\"primary\": \"#22252A\", \"secondary\": \"#2A2D32\", \"accent\": \"#B8955C\", \"text\": \"#ECE7E1\", \"background\": \"#17191C\"}'::jsonb)\nfrom public.brands b\nwhere c.brand_id = b.id and b.slug = 'bravus' and c.key = 'identity'\n  and c.value->'palette' = '{\"primary\": \"#2C2D30\", \"secondary\": \"#2C2D30\", \"accent\": \"#B87333\", \"text\": \"#ECE7E1\", \"background\": \"#1E1F21\"}'::jsonb;\n"
  },
  {
    "name": "20261001000006_whatsapp_pedidos.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · Migration 0006 — WhatsApp que recebe os pedidos\n--\n-- Número informado pelo cliente (wa.me/558173314464, o mesmo do Instagram):\n-- DDI 55 + DDD 81 + 7331-4464. Vale para as duas lojas (modelo geral) e também\n-- aparece no rodapé de cada uma. Só preenche onde o número ainda está vazio,\n-- para nunca sobrescrever o que já foi definido em WhatsApp, no painel.\n-- =============================================================================\n\nupdate public.cms_content\nset value = jsonb_set(value, '{number}', '\"558173314464\"'::jsonb, true)\nwhere key = 'whatsapp'\n  and coalesce(value->>'number', '') = '';\n"
  },
  {
    "name": "20261001000007_nome_fina_e_classica.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · Migration 0007 — nome da marca: FINA&CLÁSSICA\n--\n-- O nome oficial usa \"&\" (FINA&CLÁSSICA). Atualiza o nome da marca e o nome do\n-- site. O endereço da loja (slug \"fina-classica\") e o prefixo dos pedidos (FC)\n-- não mudam. Só altera se ainda estiver com o nome antigo.\n-- =============================================================================\n\nupdate public.brands\nset name = 'FINA&CLÁSSICA'\nwhere slug = 'fina-classica' and name = 'FINA CLÁSSICA';\n\nupdate public.cms_content\nset value = jsonb_set(value, '{name}', '\"FINA&CLÁSSICA + BRAVUS\"'::jsonb)\nwhere brand_id is null and key = 'site' and value->>'name' = 'FINA CLÁSSICA + BRAVUS';\n"
  },
  {
    "name": "20261001000008_contato_instagram_capa.sql",
    "sql": "-- =============================================================================\n-- FC-BRA · Migration 0008 — contato, Instagram e imagem da capa (FINA&CLÁSSICA)\n--\n-- Dados informados pelo cliente:\n--   * WhatsApp / telefone: (81) 97331-4464  ->  5581973314464 (DDI 55 + DDD 81 + 9 7331-4464).\n--     Substitui o número provisório 558173314464 (vindo do link do Instagram, sem o 9)\n--     e preenche WhatsApp e Telefone do rodapé das duas lojas.\n--   * Instagram da FINA&CLÁSSICA: https://www.instagram.com/finaeclassica\n--   * Imagem da capa da FINA&CLÁSSICA: /brand/fina-classica/hero.webp\n-- Só preenche o que está vazio (ou o número provisório); nunca sobrescreve o que o\n-- cliente já publicou no painel.\n-- =============================================================================\n\n-- Número que recebe os pedidos (modelo geral e por marca)\nupdate public.cms_content\nset value = jsonb_set(value, '{number}', '\"5581973314464\"'::jsonb, true)\nwhere key = 'whatsapp'\n  and coalesce(value->>'number', '') in ('', '558173314464');\n\n-- WhatsApp e telefone exibidos no rodapé de cada marca\nupdate public.cms_content\nset value = value || jsonb_build_object(\n      'whatsapp', case when coalesce(value->>'whatsapp', '') in ('', '558173314464') then '5581973314464' else value->>'whatsapp' end,\n      'phone',    case when coalesce(value->>'phone', '')    in ('', '558173314464') then '5581973314464' else value->>'phone' end)\nwhere key = 'contact' and brand_id is not null;\n\n-- Instagram da FINA&CLÁSSICA\nupdate public.cms_content c\nset value = jsonb_set(c.value, '{instagram}', '\"https://www.instagram.com/finaeclassica\"'::jsonb, true)\nfrom public.brands b\nwhere c.brand_id = b.id and b.slug = 'fina-classica' and c.key = 'social'\n  and coalesce(c.value->>'instagram', '') = '';\n\n-- Imagem da capa da FINA&CLÁSSICA\nupdate public.cms_content c\nset value = jsonb_set(c.value, '{hero_image_url}', '\"/brand/fina-classica/hero.webp\"'::jsonb, true)\nfrom public.brands b\nwhere c.brand_id = b.id and b.slug = 'fina-classica' and c.key = 'home'\n  and coalesce(c.value->>'hero_image_url', '') = '';\n"
  }
];
